<template><ion-page><ion-header><ion-toolbar color="primary"><ion-buttons slot="start"><ion-back-button default-href="/commandes" /></ion-buttons><ion-title>Commandes archivées</ion-title></ion-toolbar></ion-header><ion-content><ion-list v-if="commandes.length"><ion-item-sliding v-for="commande in commandes" :key="commande.id"><ion-item button @click="router.push('/commandes/' + commande.id)"><ion-label><h2>{{ commande.numero }}</h2><p>{{ formatDate(commande.dateCommande || commande.date_commande) }} · Archivée le {{ formatDate(commande.date_archivage) }}</p><h3>{{ Number(commande.coutTotal ?? commande.cout_total ?? 0).toFixed(2) }} {{ commande.devise }}</h3></ion-label><ion-badge color="medium">{{ commande.statut }}</ion-badge></ion-item><ion-item-options side="end"><ion-item-option color="success" @click="restore(commande)"><ion-icon slot="icon-only" :icon="arrowUndoOutline" /></ion-item-option></ion-item-options></ion-item-sliding></ion-list><div v-else class="empty-state">Aucune commande archivée.</div></ion-content></ion-page></template>
<script setup lang="ts">
import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {IonPage,IonHeader,IonToolbar,IonTitle,IonButtons,IonBackButton,IonContent,IonList,IonItemSliding,IonItem,IonItemOptions,IonItemOption,IonIcon,IonLabel,IonBadge,toastController} from '@ionic/vue';import {arrowUndoOutline} from 'ionicons/icons';import DatabaseService from '@/services/database.service';
const router=useRouter();const commandes=ref<any[]>([]);const formatDate=(v?:string)=>v?new Date(v).toLocaleDateString('fr-FR'):'—';const load=async()=>{commandes.value=await DatabaseService.getArchivedCommandes();};const restore=async(c:any)=>{try{await DatabaseService.restoreCommande(c.id);const t=await toastController.create({message:'Commande restaurée dans les commandes actives.',duration:2500,color:'success'});await t.present();await load();}catch(e){const t=await toastController.create({message:e instanceof Error?e.message:'Restauration impossible.',duration:3000,color:'danger'});await t.present();}};onMounted(load);
</script><style scoped>.empty-state{padding:3rem 1rem;text-align:center;color:var(--ion-color-medium);}</style>